#include "string.h"

#define PART_DISP_TIMES       10        // After PART_DISP_TIMES-1 partial refreshes, perform a full refresh once
static int reflesh_times = 0;

/*
 * Runtime LUT override for panel debugging (driven by the MSH commands defined
 * in B082A05_EPD.c: epd_force / epd_black / epd_white / epd_normal).
 *
 * When s_force_code != 0, every one of the 256 LUT entries is filled with that
 * single 2-bit code on every frame, so all pixels receive exactly the same drive
 * pulse whatever the framebuffer or the waveform table contains.
 *
 * This splits two failure modes that look identical on the panel:
 *   - panel turns solid black/white  -> LUT & source data path are alive,
 *                                       the waveform table content is the issue
 *   - panel does not change at all   -> LUT/source data path or EPD timing
 *                                       is broken, changing the table won't help
 *
 * s_force_code == 0 is the normal behaviour (waveform table is used).
 */
static uint8_t s_force_code = 0;

void epd_wave_force_set(uint8_t code)
{
    s_force_code = (uint8_t)(code & 0x03);
}

uint8_t epd_wave_force_get(void)
{
    return s_force_code;
}

// 8bit lookup table for the current frame (high 4 bits: old data, low 4 bits: new data).
// The output is 2-bit data.

typedef struct
{
    int min_temp;
    int max_temp;
    uint32_t frame_count;
    const uint8_t (*wave_table)[256];
} WaveTableEntry;


